def compute(vars):
    threshold = 50000
    below_threshold = {
        "2018": vars["v1"] < threshold,
        "2019": vars["v2"] < threshold,
    }
    year = next((year for year, is_below in below_threshold.items() if is_below), None)
    return {
        "value": year,
        "trace": {
            "threshold": threshold,
            "comparisons": below_threshold,
            "output_meta": {"currency": None, "scale": None, "unit": None},
        },
    }
